// cxtool computes a deterministic complexity/coverage/churn baseline for a Go
// repository and rolls it up by "feature" using a file→feature mapping.
//
//	cxtool -root . -features features.json -cover a.out,b.out -churn-days 90,180 -out out/
//
// Metrics per function: LOC, cyclomatic (gocyclo), cognitive (gocognit),
// statements + covered statements (from cover profiles, merged by max count).
// Metrics per file: the above summed, plus churn (commits / lines changed).
// Metrics per feature: the above summed over files, plus test LOC and a few
// derived ratios. Generated files (ast.IsGenerated) are tracked but excluded
// from complexity aggregates.
package main

import (
	"bufio"
	"bytes"
	"encoding/csv"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/fzipp/gocyclo"
	"github.com/uudashr/gocognit"
	"golang.org/x/tools/cover"
)

// ---------- config ----------

type FeatureRule struct {
	Name  string   `json:"name"`
	Area  string   `json:"area"`
	Paths []string `json:"paths"`
	Note  string   `json:"note,omitempty"`
}

type Config struct {
	Features []FeatureRule `json:"features"`
}

// matchRule: pattern ending in "/" is a directory-prefix match; otherwise the
// directory must match exactly and the basename is glob-matched.
func matchRule(pattern, rel string) bool {
	if strings.HasSuffix(pattern, "/") {
		return strings.HasPrefix(rel, pattern)
	}
	pdir, pbase := path.Split(pattern)
	rdir, rbase := path.Split(rel)
	if pdir != rdir {
		return false
	}
	ok, _ := path.Match(pbase, rbase)
	return ok
}

func (c *Config) featureFor(rel string) (name, area string) {
	// Test files are mapped via their source-file name.
	probe := rel
	if strings.HasSuffix(rel, "_test.go") {
		probe = strings.TrimSuffix(rel, "_test.go") + ".go"
	}
	for _, f := range c.Features {
		for _, p := range f.Paths {
			if matchRule(p, probe) || matchRule(p, rel) {
				return f.Name, f.Area
			}
		}
	}
	return "_unmapped", "_unmapped"
}

// ---------- data model ----------

type Func struct {
	File      string `json:"file"`
	Pkg       string `json:"pkg"`
	Name      string `json:"name"`
	Start     int    `json:"start"`
	End       int    `json:"end"`
	LOC       int    `json:"loc"`
	Cyclo     int    `json:"cyclo"`
	Cognit    int    `json:"cognit"`
	Stmts     int    `json:"stmts"`
	Covered   int    `json:"covered"`
	Feature   string `json:"feature"`
	Area      string `json:"area"`
	Generated bool   `json:"generated,omitempty"`
}

func (f *Func) CovPct() float64 {
	if f.Stmts == 0 {
		return -1
	}
	return 100 * float64(f.Covered) / float64(f.Stmts)
}

type Churn struct {
	Commits int `json:"commits"`
	Added   int `json:"added"`
	Deleted int `json:"deleted"`
}

type File struct {
	Rel       string           `json:"rel"`
	PkgDir    string           `json:"pkg_dir"`
	IsTest    bool             `json:"is_test"`
	Generated bool             `json:"generated"`
	LOC       int              `json:"loc"` // physical lines
	Funcs     []*Func          `json:"-"`
	Stmts     int              `json:"stmts"`
	Covered   int              `json:"covered"`
	Churn     map[string]Churn `json:"churn"` // key: "90d"
	Feature   string           `json:"feature"`
	Area      string           `json:"area"`
	Imports   []string         `json:"-"`
}

type Agg struct {
	Name        string           `json:"name"`
	Area        string           `json:"area,omitempty"`
	Files       int              `json:"files"`
	TestFiles   int              `json:"test_files"`
	ProdLOC     int              `json:"prod_loc"`
	TestLOC     int              `json:"test_loc"`
	GenLOC      int              `json:"gen_loc"`
	Funcs       int              `json:"funcs"`
	SumCyclo    int              `json:"sum_cyclo"`
	MaxCyclo    int              `json:"max_cyclo"`
	SumCognit   int              `json:"sum_cognit"`
	MaxCognit   int              `json:"max_cognit"`
	FuncsCC15   int              `json:"funcs_cyclo_gt15"`
	FuncsCog20  int              `json:"funcs_cognit_gt20"`
	Stmts       int              `json:"stmts"`
	Covered     int              `json:"covered"`
	Churn       map[string]Churn `json:"churn"`
	FanIn       int              `json:"fan_in,omitempty"`
	FanOut      int              `json:"fan_out,omitempty"`
	cognitVals  []int
	uncovCognit int // cognitive complexity in functions with <50% coverage
}

func (a *Agg) CovPct() float64 {
	if a.Stmts == 0 {
		return -1
	}
	return 100 * float64(a.Covered) / float64(a.Stmts)
}

func (a *Agg) TestRatio() float64 {
	if a.ProdLOC == 0 {
		return 0
	}
	return float64(a.TestLOC) / float64(a.ProdLOC)
}

func (a *Agg) Density() float64 { // cognitive complexity per 100 prod LOC
	if a.ProdLOC == 0 {
		return 0
	}
	return 100 * float64(a.SumCognit) / float64(a.ProdLOC)
}

func (a *Agg) MedianCognit() float64 {
	if len(a.cognitVals) == 0 {
		return 0
	}
	v := append([]int(nil), a.cognitVals...)
	sort.Ints(v)
	n := len(v)
	if n%2 == 1 {
		return float64(v[n/2])
	}
	return float64(v[n/2-1]+v[n/2]) / 2
}

func (a *Agg) add(f *File, windows []string) {
	if a.Churn == nil {
		a.Churn = map[string]Churn{}
	}
	for _, w := range windows {
		c := a.Churn[w]
		fc := f.Churn[w]
		c.Commits += fc.Commits
		c.Added += fc.Added
		c.Deleted += fc.Deleted
		a.Churn[w] = c
	}
	if f.IsTest {
		a.TestFiles++
		a.TestLOC += f.LOC
		return
	}
	a.Files++
	if f.Generated {
		a.GenLOC += f.LOC
		return
	}
	a.ProdLOC += f.LOC
	a.Stmts += f.Stmts
	a.Covered += f.Covered
	for _, fn := range f.Funcs {
		a.Funcs++
		a.SumCyclo += fn.Cyclo
		a.SumCognit += fn.Cognit
		a.cognitVals = append(a.cognitVals, fn.Cognit)
		if fn.Cyclo > a.MaxCyclo {
			a.MaxCyclo = fn.Cyclo
		}
		if fn.Cognit > a.MaxCognit {
			a.MaxCognit = fn.Cognit
		}
		if fn.Cyclo > 15 {
			a.FuncsCC15++
		}
		if fn.Cognit > 20 {
			a.FuncsCog20++
		}
		if fn.Stmts > 0 && fn.CovPct() < 50 {
			a.uncovCognit += fn.Cognit
		}
	}
}

// ---------- main ----------

func main() {
	root := flag.String("root", ".", "repository root")
	featuresPath := flag.String("features", "features.json", "feature mapping JSON")
	coverList := flag.String("cover", "", "comma-separated cover profiles (merged by max count)")
	churnDays := flag.String("churn-days", "90,180", "comma-separated churn windows in days")
	outDir := flag.String("out", "out", "output directory")
	skipDirs := flag.String("skip", ".git,node_modules,.opencode,.worktrees,.entire,.herdr", "dir names to skip")
	flag.Parse()

	absRoot, err := filepath.Abs(*root)
	check(err)
	modPath := readModulePath(absRoot)

	var cfg Config
	if b, err := os.ReadFile(*featuresPath); err == nil {
		check(json.Unmarshal(b, &cfg))
	} else {
		fmt.Fprintln(os.Stderr, "warning: no features file; everything is _unmapped")
	}

	skip := map[string]bool{}
	for _, s := range strings.Split(*skipDirs, ",") {
		skip[s] = true
	}

	// 1. Parse all Go files.
	files := map[string]*File{}
	fset := token.NewFileSet()
	check(filepath.WalkDir(absRoot, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if p != absRoot && (skip[d.Name()] || strings.HasPrefix(d.Name(), ".")) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(p, ".go") {
			return nil
		}
		rel := filepath.ToSlash(mustRel(absRoot, p))
		src, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		af, err := parser.ParseFile(fset, p, src, parser.ParseComments|parser.SkipObjectResolution)
		if err != nil {
			fmt.Fprintf(os.Stderr, "parse %s: %v\n", rel, err)
			return nil
		}
		f := &File{
			Rel:       rel,
			PkgDir:    path.Dir(rel),
			IsTest:    strings.HasSuffix(rel, "_test.go"),
			Generated: ast.IsGenerated(af),
			LOC:       bytes.Count(src, []byte("\n")),
			Churn:     map[string]Churn{},
		}
		f.Feature, f.Area = cfg.featureFor(rel)
		for _, imp := range af.Imports {
			ip, _ := strconv.Unquote(imp.Path.Value)
			if strings.HasPrefix(ip, modPath+"/") || ip == modPath {
				f.Imports = append(f.Imports, ip)
			}
		}
		if !f.IsTest {
			for _, decl := range af.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Body == nil {
					continue
				}
				start := fset.Position(fn.Pos()).Line
				end := fset.Position(fn.End()).Line
				f.Funcs = append(f.Funcs, &Func{
					File:      rel,
					Pkg:       af.Name.Name,
					Name:      funcName(fn),
					Start:     start,
					End:       end,
					LOC:       end - start + 1,
					Cyclo:     gocyclo.Complexity(fn),
					Cognit:    gocognit.Complexity(fn),
					Feature:   f.Feature,
					Area:      f.Area,
					Generated: f.Generated,
				})
			}
			sort.Slice(f.Funcs, func(i, j int) bool { return f.Funcs[i].Start < f.Funcs[j].Start })
		}
		files[rel] = f
		return nil
	}))

	// 2. Coverage: merge profiles by block (max count), attribute to functions.
	if *coverList != "" {
		type blockKey struct {
			file                   string
			sl, sc, el, ec, nstmts int
		}
		merged := map[blockKey]int{}
		for _, cp := range strings.Split(*coverList, ",") {
			cp = strings.TrimSpace(cp)
			if cp == "" {
				continue
			}
			profiles, err := cover.ParseProfiles(cp)
			check(err)
			for _, pr := range profiles {
				rel := strings.TrimPrefix(pr.FileName, modPath+"/")
				for _, b := range pr.Blocks {
					k := blockKey{rel, b.StartLine, b.StartCol, b.EndLine, b.EndCol, b.NumStmt}
					if b.Count > merged[k] {
						merged[k] = b.Count
					}
				}
			}
		}
		missing := map[string]bool{}
		for k, cnt := range merged {
			f := files[k.file]
			if f == nil {
				missing[k.file] = true
				continue
			}
			f.Stmts += k.nstmts
			if cnt > 0 {
				f.Covered += k.nstmts
			}
			// attribute to enclosing function by start line
			i := sort.Search(len(f.Funcs), func(i int) bool { return f.Funcs[i].Start > k.sl }) - 1
			if i >= 0 && f.Funcs[i].End >= k.sl {
				f.Funcs[i].Stmts += k.nstmts
				if cnt > 0 {
					f.Funcs[i].Covered += k.nstmts
				}
			}
		}
		if len(missing) > 0 {
			fmt.Fprintf(os.Stderr, "coverage: %d profile files not found in tree (first: %s)\n", len(missing), firstKey(missing))
		}
	}

	// 3. Churn.
	windows := []string{}
	for _, d := range strings.Split(*churnDays, ",") {
		d = strings.TrimSpace(d)
		if d == "" {
			continue
		}
		w := d + "d"
		windows = append(windows, w)
		for rel, c := range gitChurn(absRoot, d) {
			if f := files[rel]; f != nil {
				f.Churn[w] = c
			}
		}
	}

	// 4. Aggregate: features, areas, packages, fan-in/out.
	features := map[string]*Agg{}
	areas := map[string]*Agg{}
	pkgs := map[string]*Agg{}
	pkgImports := map[string]map[string]bool{} // pkgDir -> set of imported pkgDirs
	for _, f := range files {
		get(features, f.Feature).Area = f.Area
		get(features, f.Feature).add(f, windows)
		get(areas, f.Area).add(f, windows)
		get(pkgs, f.PkgDir).add(f, windows)
		if !f.IsTest {
			if pkgImports[f.PkgDir] == nil {
				pkgImports[f.PkgDir] = map[string]bool{}
			}
			for _, ip := range f.Imports {
				dep := strings.TrimPrefix(ip, modPath+"/")
				if dep == modPath {
					dep = "."
				}
				if dep != f.PkgDir {
					pkgImports[f.PkgDir][dep] = true
				}
			}
		}
	}
	fanIn := map[string]int{}
	for p, deps := range pkgImports {
		get(pkgs, p).FanOut = len(deps)
		for d := range deps {
			fanIn[d]++
		}
	}
	for p, n := range fanIn {
		if a := pkgs[p]; a != nil {
			a.FanIn = n
		}
	}

	// 5. Write outputs.
	check(os.MkdirAll(*outDir, 0o755))
	var allFuncs []*Func
	var fileList []*File
	for _, f := range files {
		fileList = append(fileList, f)
		if !f.IsTest && !f.Generated {
			allFuncs = append(allFuncs, f.Funcs...)
		}
	}
	sort.Slice(fileList, func(i, j int) bool { return fileList[i].Rel < fileList[j].Rel })
	sort.Slice(allFuncs, func(i, j int) bool {
		if allFuncs[i].Cognit != allFuncs[j].Cognit {
			return allFuncs[i].Cognit > allFuncs[j].Cognit
		}
		return allFuncs[i].File+allFuncs[i].Name < allFuncs[j].File+allFuncs[j].Name
	})

	writeFuncsCSV(filepath.Join(*outDir, "functions.csv"), allFuncs)
	writeAggCSV(filepath.Join(*outDir, "features.csv"), sortedAggs(features), windows, false)
	writeAggCSV(filepath.Join(*outDir, "areas.csv"), sortedAggs(areas), windows, false)
	writeAggCSV(filepath.Join(*outDir, "packages.csv"), sortedAggs(pkgs), windows, true)
	writeFilesCSV(filepath.Join(*outDir, "files.csv"), fileList, windows)
	writeMarkdown(filepath.Join(*outDir, "report.md"), sortedAggs(areas), sortedAggs(features), sortedAggs(pkgs), allFuncs, fileList, windows)

	// Full JSON for downstream rendering.
	type out struct {
		Module   string           `json:"module"`
		Windows  []string         `json:"windows"`
		Areas    []*Agg           `json:"areas"`
		Features []*Agg           `json:"features"`
		Packages []*Agg           `json:"packages"`
		Files    []*File          `json:"files"`
		Funcs    []*Func          `json:"funcs"`
		PkgDeps  map[string][]string `json:"pkg_deps"`
	}
	deps := map[string][]string{}
	for p, s := range pkgImports {
		for d := range s {
			deps[p] = append(deps[p], d)
		}
		sort.Strings(deps[p])
	}
	b, err := json.MarshalIndent(out{modPath, windows, sortedAggs(areas), sortedAggs(features), sortedAggs(pkgs), fileList, allFuncs, deps}, "", " ")
	check(err)
	check(os.WriteFile(filepath.Join(*outDir, "report.json"), b, 0o644))

	// Unmapped summary on stderr so the mapping can be iterated.
	if u := features["_unmapped"]; u != nil {
		fmt.Fprintf(os.Stderr, "unmapped: %d files, %d prod LOC\n", u.Files+u.TestFiles, u.ProdLOC)
		for _, f := range fileList {
			if f.Feature == "_unmapped" {
				fmt.Fprintf(os.Stderr, "  %s\n", f.Rel)
			}
		}
	}
	fmt.Fprintf(os.Stderr, "wrote %s/{report.md,report.json,functions.csv,features.csv,areas.csv,packages.csv,files.csv}\n", *outDir)
}

// ---------- helpers ----------

func check(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

func mustRel(base, p string) string {
	r, err := filepath.Rel(base, p)
	check(err)
	return r
}

func firstKey(m map[string]bool) string {
	for k := range m {
		return k
	}
	return ""
}

func get(m map[string]*Agg, k string) *Agg {
	a := m[k]
	if a == nil {
		a = &Agg{Name: k, Churn: map[string]Churn{}}
		m[k] = a
	}
	return a
}

func sortedAggs(m map[string]*Agg) []*Agg {
	var out []*Agg
	for _, a := range m {
		out = append(out, a)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].SumCognit != out[j].SumCognit {
			return out[i].SumCognit > out[j].SumCognit
		}
		return out[i].Name < out[j].Name
	})
	return out
}

func readModulePath(root string) string {
	b, err := os.ReadFile(filepath.Join(root, "go.mod"))
	check(err)
	for _, l := range strings.Split(string(b), "\n") {
		if strings.HasPrefix(l, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(l, "module "))
		}
	}
	check(fmt.Errorf("no module line in go.mod"))
	return ""
}

func funcName(fn *ast.FuncDecl) string {
	if fn.Recv == nil || len(fn.Recv.List) == 0 {
		return fn.Name.Name
	}
	t := fn.Recv.List[0].Type
	for {
		switch x := t.(type) {
		case *ast.StarExpr:
			t = x.X
			continue
		case *ast.IndexExpr:
			t = x.X
			continue
		case *ast.IndexListExpr:
			t = x.X
			continue
		case *ast.Ident:
			return x.Name + "." + fn.Name.Name
		}
		return "?." + fn.Name.Name
	}
}

// gitChurn returns per-file churn over the last N days (no rename following:
// a renamed file's old path simply falls off the tree and is dropped).
func gitChurn(root, days string) map[string]Churn {
	cmd := exec.Command("git", "-C", root, "log", "--since="+days+" days ago", "--numstat", "--no-renames", "--format=%H", "--", "*.go")
	out, err := cmd.Output()
	check(err)
	res := map[string]Churn{}
	seen := map[string]map[string]bool{} // file -> commit set
	var commit string
	sc := bufio.NewScanner(bytes.NewReader(out))
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		l := sc.Text()
		if l == "" {
			continue
		}
		parts := strings.Split(l, "\t")
		if len(parts) == 1 {
			commit = l
			continue
		}
		if len(parts) != 3 {
			continue
		}
		add, _ := strconv.Atoi(parts[0]) // "-" for binary → 0
		del, _ := strconv.Atoi(parts[1])
		file := parts[2]
		c := res[file]
		if seen[file] == nil {
			seen[file] = map[string]bool{}
		}
		if !seen[file][commit] {
			seen[file][commit] = true
			c.Commits++
		}
		c.Added += add
		c.Deleted += del
		res[file] = c
	}
	return res
}

func pct(v float64) string {
	if v < 0 {
		return "n/a"
	}
	return fmt.Sprintf("%.1f", v)
}

// ---------- writers ----------

func writeFuncsCSV(p string, fns []*Func) {
	f, err := os.Create(p)
	check(err)
	defer f.Close()
	w := csv.NewWriter(f)
	_ = w.Write([]string{"feature", "area", "file", "pkg", "func", "start", "loc", "cyclo", "cognit", "stmts", "covered", "cov_pct"})
	for _, fn := range fns {
		_ = w.Write([]string{fn.Feature, fn.Area, fn.File, fn.Pkg, fn.Name, itoa(fn.Start), itoa(fn.LOC), itoa(fn.Cyclo), itoa(fn.Cognit), itoa(fn.Stmts), itoa(fn.Covered), pct(fn.CovPct())})
	}
	w.Flush()
}

func writeAggCSV(p string, aggs []*Agg, windows []string, withFan bool) {
	f, err := os.Create(p)
	check(err)
	defer f.Close()
	w := csv.NewWriter(f)
	hdr := []string{"name", "area", "files", "test_files", "prod_loc", "test_loc", "gen_loc", "test_ratio", "funcs", "sum_cyclo", "max_cyclo", "sum_cognit", "max_cognit", "median_cognit", "cognit_per_100loc", "funcs_cyclo_gt15", "funcs_cognit_gt20", "stmts", "covered", "cov_pct", "uncovered_cognit"}
	for _, wn := range windows {
		hdr = append(hdr, "commits_"+wn, "lines_changed_"+wn)
	}
	if withFan {
		hdr = append(hdr, "fan_in", "fan_out")
	}
	_ = w.Write(hdr)
	for _, a := range aggs {
		row := []string{a.Name, a.Area, itoa(a.Files), itoa(a.TestFiles), itoa(a.ProdLOC), itoa(a.TestLOC), itoa(a.GenLOC), fmt.Sprintf("%.2f", a.TestRatio()), itoa(a.Funcs), itoa(a.SumCyclo), itoa(a.MaxCyclo), itoa(a.SumCognit), itoa(a.MaxCognit), fmt.Sprintf("%.1f", a.MedianCognit()), fmt.Sprintf("%.1f", a.Density()), itoa(a.FuncsCC15), itoa(a.FuncsCog20), itoa(a.Stmts), itoa(a.Covered), pct(a.CovPct()), itoa(a.uncovCognit)}
		for _, wn := range windows {
			c := a.Churn[wn]
			row = append(row, itoa(c.Commits), itoa(c.Added+c.Deleted))
		}
		if withFan {
			row = append(row, itoa(a.FanIn), itoa(a.FanOut))
		}
		_ = w.Write(row)
	}
	w.Flush()
}

func writeFilesCSV(p string, files []*File, windows []string) {
	f, err := os.Create(p)
	check(err)
	defer f.Close()
	w := csv.NewWriter(f)
	hdr := []string{"feature", "area", "file", "is_test", "generated", "loc", "funcs", "sum_cyclo", "sum_cognit", "max_cognit", "stmts", "covered", "cov_pct"}
	for _, wn := range windows {
		hdr = append(hdr, "commits_"+wn, "lines_changed_"+wn)
	}
	_ = w.Write(hdr)
	for _, fl := range files {
		sc, sg, mg := 0, 0, 0
		for _, fn := range fl.Funcs {
			sc += fn.Cyclo
			sg += fn.Cognit
			if fn.Cognit > mg {
				mg = fn.Cognit
			}
		}
		cov := -1.0
		if fl.Stmts > 0 {
			cov = 100 * float64(fl.Covered) / float64(fl.Stmts)
		}
		row := []string{fl.Feature, fl.Area, fl.Rel, strconv.FormatBool(fl.IsTest), strconv.FormatBool(fl.Generated), itoa(fl.LOC), itoa(len(fl.Funcs)), itoa(sc), itoa(sg), itoa(mg), itoa(fl.Stmts), itoa(fl.Covered), pct(cov)}
		for _, wn := range windows {
			c := fl.Churn[wn]
			row = append(row, itoa(c.Commits), itoa(c.Added+c.Deleted))
		}
		_ = w.Write(row)
	}
	w.Flush()
}

func itoa(i int) string { return strconv.Itoa(i) }

func writeMarkdown(p string, areas, features, pkgs []*Agg, fns []*Func, files []*File, windows []string) {
	var b strings.Builder
	w0 := windows[0]
	fmt.Fprintf(&b, "# Complexity baseline\n\n")
	fmt.Fprintf(&b, "## By area\n\n")
	aggTable(&b, areas, w0, false)
	fmt.Fprintf(&b, "\n## By feature\n\n")
	aggTable(&b, features, w0, false)
	fmt.Fprintf(&b, "\n## By package (top 40 by cognitive complexity)\n\n")
	if len(pkgs) > 40 {
		pkgs = pkgs[:40]
	}
	aggTable(&b, pkgs, w0, true)

	fmt.Fprintf(&b, "\n## Top 40 functions by cognitive complexity\n\n")
	fmt.Fprintf(&b, "| cognit | cyclo | loc | cov%% | feature | function |\n|---:|---:|---:|---:|---|---|\n")
	for i, fn := range fns {
		if i >= 40 {
			break
		}
		fmt.Fprintf(&b, "| %d | %d | %d | %s | %s | `%s:%d` %s |\n", fn.Cognit, fn.Cyclo, fn.LOC, pct(fn.CovPct()), fn.Feature, fn.File, fn.Start, fn.Name)
	}

	fmt.Fprintf(&b, "\n## Complex and under-covered (cognit ≥ 15, coverage < 50%%)\n\n")
	fmt.Fprintf(&b, "| cognit | cyclo | loc | cov%% | feature | function |\n|---:|---:|---:|---:|---|---|\n")
	n := 0
	for _, fn := range fns {
		if fn.Cognit >= 15 && fn.Stmts > 0 && fn.CovPct() < 50 {
			fmt.Fprintf(&b, "| %d | %d | %d | %s | %s | `%s:%d` %s |\n", fn.Cognit, fn.Cyclo, fn.LOC, pct(fn.CovPct()), fn.Feature, fn.File, fn.Start, fn.Name)
			n++
			if n >= 60 {
				break
			}
		}
	}

	// File hotspots: churn × complexity
	type hs struct {
		f     *File
		score float64
		sg    int
	}
	var hot []hs
	for _, f := range files {
		if f.IsTest || f.Generated {
			continue
		}
		sg := 0
		for _, fn := range f.Funcs {
			sg += fn.Cognit
		}
		c := f.Churn[w0].Commits
		if c > 0 && sg > 0 {
			hot = append(hot, hs{f, float64(c) * float64(sg), sg})
		}
	}
	sort.Slice(hot, func(i, j int) bool { return hot[i].score > hot[j].score })
	fmt.Fprintf(&b, "\n## File hotspots: commits(%s) × cognitive complexity (top 40)\n\n", w0)
	fmt.Fprintf(&b, "| commits | sum cognit | loc | cov%% | feature | file |\n|---:|---:|---:|---:|---|---|\n")
	for i, h := range hot {
		if i >= 40 {
			break
		}
		cov := -1.0
		if h.f.Stmts > 0 {
			cov = 100 * float64(h.f.Covered) / float64(h.f.Stmts)
		}
		fmt.Fprintf(&b, "| %d | %d | %d | %s | %s | `%s` |\n", h.f.Churn[w0].Commits, h.sg, h.f.LOC, pct(cov), h.f.Feature, h.f.Rel)
	}
	check(os.WriteFile(p, []byte(b.String()), 0o644))
}

func aggTable(b *strings.Builder, aggs []*Agg, w0 string, withFan bool) {
	fmt.Fprintf(b, "| name | area | prod LOC | test LOC | ratio | funcs | Σcognit | cog/100loc | max cog | >20 cog | cov%% | uncov cog | commits %s", w0)
	if withFan {
		fmt.Fprintf(b, " | in | out")
	}
	fmt.Fprintf(b, " |\n|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:")
	if withFan {
		fmt.Fprintf(b, "|---:|---:")
	}
	fmt.Fprintf(b, "|\n")
	for _, a := range aggs {
		fmt.Fprintf(b, "| %s | %s | %d | %d | %.2f | %d | %d | %.1f | %d | %d | %s | %d | %d", a.Name, a.Area, a.ProdLOC, a.TestLOC, a.TestRatio(), a.Funcs, a.SumCognit, a.Density(), a.MaxCognit, a.FuncsCog20, pct(a.CovPct()), a.uncovCognit, a.Churn[w0].Commits)
		if withFan {
			fmt.Fprintf(b, " | %d | %d", a.FanIn, a.FanOut)
		}
		fmt.Fprintf(b, " |\n")
	}
}

