// reach computes, for every cobra command constructor in the module, the set of
// module functions reachable from it (call graph + closures + function values),
// and splits that into EXCLUSIVE (reached by no other command) vs SHARED.
//
//	reach -root . -features ../features.json -out out/reach
//
// Roots: every function whose result type is *cobra.Command. Traversal stops
// at other roots, so a group constructor's set is its own glue only, and a
// leaf's set is its own work. Metrics are attributed to top-level FuncDecls
// (closures roll up to their enclosing declaration, which is also how gocognit
// counts them).
package main

import (
	"encoding/csv"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/uudashr/gocognit"
	"golang.org/x/tools/go/callgraph"
	"golang.org/x/tools/go/callgraph/vta"
	"golang.org/x/tools/go/packages"
	"golang.org/x/tools/go/ssa"
	"golang.org/x/tools/go/ssa/ssautil"
)

type FeatureRule struct {
	Name  string   `json:"name"`
	Area  string   `json:"area"`
	Paths []string `json:"paths"`
}
type Config struct {
	Features []FeatureRule `json:"features"`
}

func matchRule(pattern, rel string) bool {
	if strings.HasSuffix(pattern, "/") {
		return strings.HasPrefix(rel, pattern)
	}
	pdir, pbase := path.Split(pattern)
	rdir, rbase := path.Split(rel)
	if pdir != rdir {
		return false
	}
	ok, _ := path.Match(pbase, rbase)
	return ok
}

func (c *Config) featureFor(rel string) string {
	for _, f := range c.Features {
		for _, p := range f.Paths {
			if matchRule(p, rel) {
				return f.Name
			}
		}
	}
	return "_unmapped"
}

// decl is a top-level function declaration with metrics.
type decl struct {
	Key    string `json:"key"` // pkgpath.Func or pkgpath.Recv.Func
	File   string `json:"file"`
	Line   int    `json:"line"`
	LOC    int    `json:"loc"`
	Cognit int    `json:"cognit"`
	Feat   string `json:"feature"`
}

type cmdResult struct {
	Root          string         `json:"root"`
	Pkg           string         `json:"pkg"`
	File          string         `json:"file"`
	ReachDecls    int            `json:"reach_decls"`
	ReachLOC      int            `json:"reach_loc"`
	ReachCognit   int            `json:"reach_cognit"`
	ExclDecls     int            `json:"excl_decls"`
	ExclLOC       int            `json:"excl_loc"`
	ExclCognit    int            `json:"excl_cognit"`
	ExclFeatures  map[string]int `json:"excl_features_loc"` // feature -> exclusive LOC
	ReachFeatures map[string]int `json:"reach_features_loc"`
	ExclDeclKeys  []string       `json:"excl_decl_keys"`
}

func main() {
	root := flag.String("root", ".", "module root")
	featuresPath := flag.String("features", "features.json", "feature mapping")
	outDir := flag.String("out", "out/reach", "output dir")
	algo := flag.String("algo", "vta", "callgraph algorithm: vta|cha")
	flag.Parse()

	absRoot, err := filepath.Abs(*root)
	check(err)
	var cfg Config
	if b, err := os.ReadFile(*featuresPath); err == nil {
		check(json.Unmarshal(b, &cfg))
	}

	t0 := time.Now()
	pcfg := &packages.Config{
		Mode: packages.LoadAllSyntax,
		Dir:  absRoot,
		// Include test-tagged files? No: production reachability only.
	}
	pkgs, err := packages.Load(pcfg, "./...")
	check(err)
	if packages.PrintErrors(pkgs) > 0 {
		fmt.Fprintln(os.Stderr, "warning: some packages had errors; continuing")
	}
	modPath := pkgs[0].Module.Path
	fmt.Fprintf(os.Stderr, "loaded %d packages in %s\n", len(pkgs), time.Since(t0).Round(time.Millisecond))

	t0 = time.Now()
	prog, _ := ssautil.AllPackages(pkgs, ssa.InstantiateGenerics)
	prog.Build()
	fmt.Fprintf(os.Stderr, "built SSA in %s\n", time.Since(t0).Round(time.Millisecond))

	allFuncs := ssautil.AllFunctions(prog)
	t0 = time.Now()
	var cg *callgraph.Graph
	switch *algo {
	case "cha":
		cg = chaGraph(prog)
	default:
		cg = vta.CallGraph(allFuncs, nil)
	}
	fmt.Fprintf(os.Stderr, "callgraph (%s) with %d nodes in %s\n", *algo, len(cg.Nodes), time.Since(t0).Round(time.Millisecond))

	// Index top-level decls with metrics, keyed by *ssa.Function of the decl.
	fset := prog.Fset
	declOf := map[*ssa.Function]*decl{}
	var cobraCmdType types.Type
	isModule := func(fn *ssa.Function) bool {
		return fn.Pkg != nil && strings.HasPrefix(fn.Pkg.Pkg.Path(), modPath)
	}
	topDecl := func(fn *ssa.Function) *ssa.Function {
		for fn.Parent() != nil {
			fn = fn.Parent()
		}
		return fn
	}
	for fn := range allFuncs {
		if !isModule(fn) || fn.Parent() != nil || fn.Synthetic != "" {
			continue
		}
		fd, ok := fn.Syntax().(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		pos := fset.Position(fd.Pos())
		rel, _ := filepath.Rel(absRoot, pos.Filename)
		rel = filepath.ToSlash(rel)
		if strings.HasSuffix(rel, "_test.go") {
			continue
		}
		end := fset.Position(fd.End()).Line
		declOf[fn] = &decl{
			Key:    fn.String(),
			File:   rel,
			Line:   pos.Line,
			LOC:    end - pos.Line + 1,
			Cognit: gocognit.Complexity(fd),
			Feat:   cfg.featureFor(rel),
		}
		// Detect roots: result type *cobra.Command
		if cobraCmdType == nil {
			if sig := fn.Signature; sig.Results().Len() == 1 {
				if isCobraCmdPtr(sig.Results().At(0).Type()) {
					cobraCmdType = sig.Results().At(0).Type()
				}
			}
		}
	}
	// roots
	roots := map[*ssa.Function]bool{}
	for fn := range declOf {
		sig := fn.Signature
		if sig.Results().Len() == 1 && isCobraCmdPtr(sig.Results().At(0).Type()) {
			roots[fn] = true
		}
	}
	fmt.Fprintf(os.Stderr, "%d module decls, %d cobra roots\n", len(declOf), len(roots))

	// BFS from each root over: callgraph edges + function-value operands + anon funcs.
	// Stop at (do not enter) other roots.
	succ := func(fn *ssa.Function) []*ssa.Function {
		var out []*ssa.Function
		if n := cg.Nodes[fn]; n != nil {
			for _, e := range n.Out {
				out = append(out, e.Callee.Func)
			}
		}
		for _, b := range fn.Blocks {
			for _, ins := range b.Instrs {
				var ops []*ssa.Value
				ops = ins.Operands(ops)
				for _, op := range ops {
					if op == nil {
						continue
					}
					if f, ok := (*op).(*ssa.Function); ok {
						out = append(out, f)
					}
				}
			}
		}
		out = append(out, fn.AnonFuncs...)
		return out
	}
	reach := map[*ssa.Function]map[*ssa.Function]bool{} // root -> set of top decls
	for r := range roots {
		seen := map[*ssa.Function]bool{r: true}
		queue := []*ssa.Function{r}
		decls := map[*ssa.Function]bool{}
		for len(queue) > 0 {
			f := queue[0]
			queue = queue[1:]
			if isModule(f) {
				if d := topDecl(f); declOf[d] != nil {
					decls[d] = true
				}
			}
			for _, s := range succ(f) {
				if seen[s] {
					continue
				}
				// Do not enter other cobra roots (or their closures).
				if td := topDecl(s); td != r && roots[td] {
					continue
				}
				// Do not traverse outside the module (deps/stdlib), but keep
				// edges that come back in via callbacks: we still visit
				// non-module callees one level so dynamic dispatch through
				// stdlib (sort.Slice, etc.) can return into module code.
				seen[s] = true
				if !isModule(s) && !isModule(f) {
					continue // don't wander deep inside deps
				}
				queue = append(queue, s)
			}
		}
		reach[r] = decls
	}

	// Ownership counts.
	owners := map[*ssa.Function]int{}
	for _, set := range reach {
		for d := range set {
			owners[d]++
		}
	}

	var results []*cmdResult
	for r, set := range reach {
		rd := declOf[r]
		res := &cmdResult{Root: r.String(), Pkg: r.Pkg.Pkg.Path(), File: rd.File, ExclFeatures: map[string]int{}, ReachFeatures: map[string]int{}}
		for d := range set {
			m := declOf[d]
			res.ReachDecls++
			res.ReachLOC += m.LOC
			res.ReachCognit += m.Cognit
			res.ReachFeatures[m.Feat] += m.LOC
			if owners[d] == 1 {
				res.ExclDecls++
				res.ExclLOC += m.LOC
				res.ExclCognit += m.Cognit
				res.ExclFeatures[m.Feat] += m.LOC
				res.ExclDeclKeys = append(res.ExclDeclKeys, m.Key)
			}
		}
		sort.Strings(res.ExclDeclKeys)
		results = append(results, res)
	}
	sort.Slice(results, func(i, j int) bool { return results[i].ReachLOC > results[j].ReachLOC })

	// Decls reached by no root at all (dead from the CLI's perspective, or only
	// reachable via main/plugin dispatch/tests).
	var unreached []*decl
	for fn, d := range declOf {
		if owners[fn] == 0 && !roots[fn] {
			unreached = append(unreached, d)
		}
	}
	sort.Slice(unreached, func(i, j int) bool { return unreached[i].File+strconv.Itoa(unreached[i].Line) < unreached[j].File+strconv.Itoa(unreached[j].Line) })

	check(os.MkdirAll(*outDir, 0o755))
	// CSV
	f, err := os.Create(filepath.Join(*outDir, "commands.csv"))
	check(err)
	w := csv.NewWriter(f)
	_ = w.Write([]string{"root", "file", "reach_decls", "reach_loc", "reach_cognit", "excl_decls", "excl_loc", "excl_cognit", "excl_pct_of_reach_loc", "top_excl_features"})
	for _, r := range results {
		pct := 0.0
		if r.ReachLOC > 0 {
			pct = 100 * float64(r.ExclLOC) / float64(r.ReachLOC)
		}
		_ = w.Write([]string{r.Root, r.File, itoa(r.ReachDecls), itoa(r.ReachLOC), itoa(r.ReachCognit), itoa(r.ExclDecls), itoa(r.ExclLOC), itoa(r.ExclCognit), fmt.Sprintf("%.0f", pct), topFeatures(r.ExclFeatures, 3)})
	}
	w.Flush()
	f.Close()

	// Shared-ness histogram of decls: how many commands reach each decl.
	hist := map[int]int{}
	histLOC := map[int]int{}
	for fn, d := range declOf {
		if roots[fn] {
			continue
		}
		hist[owners[fn]]++
		histLOC[owners[fn]] += d.LOC
	}

	out := map[string]any{
		"module":        modPath,
		"algo":          *algo,
		"roots":         len(roots),
		"decls":         len(declOf),
		"commands":      results,
		"owner_hist":    hist,
		"owner_histloc": histLOC,
		"unreached":     unreached,
	}
	b, err := json.MarshalIndent(out, "", " ")
	check(err)
	check(os.WriteFile(filepath.Join(*outDir, "reach.json"), b, 0o644))

	// Markdown summary
	var sb strings.Builder
	fmt.Fprintf(&sb, "# Command reachability (%s)\n\n%d cobra roots, %d module decls.\n\n", *algo, len(roots), len(declOf))
	fmt.Fprintf(&sb, "## How shared is the code? (decls by number of commands reaching them)\n\n| reached by N commands | decls | LOC |\n|---:|---:|---:|\n")
	var ks []int
	for k := range hist {
		ks = append(ks, k)
	}
	sort.Ints(ks)
	for _, k := range ks {
		fmt.Fprintf(&sb, "| %d | %d | %d |\n", k, hist[k], histLOC[k])
	}
	fmt.Fprintf(&sb, "\n## Per command\n\n| root | reach LOC | reach cognit | excl LOC | excl cognit | excl%% | top exclusive features |\n|---|---:|---:|---:|---:|---:|---|\n")
	for _, r := range results {
		pct := 0.0
		if r.ReachLOC > 0 {
			pct = 100 * float64(r.ExclLOC) / float64(r.ReachLOC)
		}
		fmt.Fprintf(&sb, "| `%s` | %d | %d | %d | %d | %.0f | %s |\n", shortRoot(r.Root, modPath), r.ReachLOC, r.ReachCognit, r.ExclLOC, r.ExclCognit, pct, topFeatures(r.ExclFeatures, 3))
	}
	fmt.Fprintf(&sb, "\n## Decls reached by no cobra command (%d)\n\nMay be: reached only via main/plugin dispatch, exported for tests, or dead.\n\n", len(unreached))
	byFeat := map[string]int{}
	for _, d := range unreached {
		byFeat[d.Feat] += d.LOC
	}
	fmt.Fprintf(&sb, "| feature | unreached LOC |\n|---|---:|\n")
	for _, kv := range sortedKV(byFeat) {
		fmt.Fprintf(&sb, "| %s | %d |\n", kv.k, kv.v)
	}
	fmt.Fprintf(&sb, "\n<details><summary>full list</summary>\n\n")
	for _, d := range unreached {
		fmt.Fprintf(&sb, "- `%s:%d` %s (%d loc, cog %d)\n", d.File, d.Line, d.Key, d.LOC, d.Cognit)
	}
	fmt.Fprintf(&sb, "\n</details>\n")
	check(os.WriteFile(filepath.Join(*outDir, "reach.md"), []byte(sb.String()), 0o644))
	fmt.Fprintf(os.Stderr, "wrote %s/{reach.md,reach.json,commands.csv}\n", *outDir)
}

func isCobraCmdPtr(t types.Type) bool {
	p, ok := t.(*types.Pointer)
	if !ok {
		return false
	}
	n, ok := p.Elem().(*types.Named)
	if !ok {
		return false
	}
	return n.Obj().Name() == "Command" && n.Obj().Pkg() != nil && strings.HasSuffix(n.Obj().Pkg().Path(), "spf13/cobra")
}

type kv struct {
	k string
	v int
}

func sortedKV(m map[string]int) []kv {
	var out []kv
	for k, v := range m {
		out = append(out, kv{k, v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].v != out[j].v {
			return out[i].v > out[j].v
		}
		return out[i].k < out[j].k
	})
	return out
}

func topFeatures(m map[string]int, n int) string {
	var parts []string
	for i, e := range sortedKV(m) {
		if i >= n {
			break
		}
		parts = append(parts, fmt.Sprintf("%s=%d", e.k, e.v))
	}
	return strings.Join(parts, " ")
}

func shortRoot(s, mod string) string {
	s = strings.TrimPrefix(s, mod+"/")
	s = strings.TrimPrefix(s, "cmd/entire/cli.")
	return s
}

func itoa(i int) string { return strconv.Itoa(i) }

func check(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

// chaGraph is kept behind a flag for comparison; imported lazily to keep the
// default path VTA.
func chaGraph(prog *ssa.Program) *callgraph.Graph {
	return chaCallGraph(prog)
}

var _ = token.NoPos

