	}
	n, ok := p.Elem().(*types.Named)
	if !ok {
		return false
	}
	return n.Obj().Name() == "Command" && n.Obj().Pkg() != nil && strings.HasSuffix(n.Obj().Pkg().Path(), "spf13/cobra")
}

type kv struct {
	k string
	v int
}

func sortedKV(m map[string]int) []kv {
	var out []kv
	for k, v := range m {
		out = append(out, kv{k, v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].v != out[j].v {
			return out[i].v > out[j].v
		}
		return out[i].k < out[j].k
	})
	return out
}

func topFeatures(m map[string]int, n int) string {
	var parts []string
	for i, e := range sortedKV(m) {
		if i >= n {
			break
		}
		parts = append(parts, fmt.Sprintf("%s=%d", e.k, e.v))
	}
	return strings.Join(parts, " ")
}

func shortRoot(s, mod string) string {
	s = strings.ReplaceAll(s, mod+"/cmd/entire/cli.", "")
	s = strings.ReplaceAll(s, mod+"/", "")
	return s
}

func itoa(i int) string { return strconv.Itoa(i) }

func readModulePath(root string) string {
	b, err := os.ReadFile(filepath.Join(root, "go.mod"))
	check(err)
	for _, l := range strings.Split(string(b), "\n") {
		if strings.HasPrefix(l, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(l, "module "))
		}
	}
	check(fmt.Errorf("no module line in go.mod"))
	return ""
}

func check(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}
