// reach computes, for every cobra command constructor in the module, the set of
// module functions reachable from it (call graph + closures + function values),
// and splits that into EXCLUSIVE (reached by no other root) vs SHARED.
//
//	reach -root . -features features.json -out out/reach [-algo vta|cha] [-who substr]
//
// Roots:
//   - every function whose result type is *cobra.Command (one root each);
//   - one pseudo-root "<init>" for all package initializers (var initializers,
//     init() functions) — code that runs at program start belongs to no command;
//   - one pseudo-root "<main:pkg>" per main package.
//
// Traversal stops at other cobra roots, so a group constructor's set is its own
// glue only, and a leaf's set is its own work. Metrics are attributed to
// top-level FuncDecls (closures roll up to their enclosing declaration, which is
// also how gocognit counts them; generic instantiations roll up to their
// origin). Test files are excluded, so "unreached" means "nothing in the
// shipped binaries references this" (modulo reflection).
//
// Precision policies, in one place because they are the tool:
//   - VTA falls back to "every function with this signature" for dynamic calls
//     it cannot resolve; call sites resolving to more than -maxfanout callees
//     are treated as unresolved noise and dropped.
//   - A closure can only run if its creator ran: an anonymous function is never
//     entered through a call edge unless its declaration was already visited
//     (its parent's expansion enqueues it legitimately).
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"cxtool/internal/cx"

	"github.com/uudashr/gocognit"
	"golang.org/x/tools/go/callgraph"
	"golang.org/x/tools/go/callgraph/cha"
	"golang.org/x/tools/go/callgraph/vta"
	"golang.org/x/tools/go/packages"
	"golang.org/x/tools/go/ssa"
	"golang.org/x/tools/go/ssa/ssautil"
)

type decl struct {
	Key    string `json:"key"`
	Name   string `json:"name"`
	File   string `json:"file"`
	Line   int    `json:"line"`
	LOC    int    `json:"loc"`
	Cognit int    `json:"cognit"`
	Feat   string `json:"feature"`
	Area   string `json:"area"`
	Ranked bool   `json:"ranked"`
}

type cmdResult struct {
	Root          string         `json:"root"`
	Kind          string         `json:"kind"` // cobra | init | main
	File          string         `json:"file"`
	Feature       string         `json:"feature"`
	ReachDecls    int            `json:"reach_decls"`
	ReachLOC      int            `json:"reach_loc"`
	ReachCognit   int            `json:"reach_cognit"`
	ExclDecls     int            `json:"excl_decls"`
	ExclLOC       int            `json:"excl_loc"`
	ExclCognit    int            `json:"excl_cognit"`
	ExclFeatures  map[string]int `json:"excl_features_loc"`
	ReachFeatures map[string]int `json:"reach_features_loc"`
}

type root struct {
	label string
	kind  string
	fns   []*ssa.Function // entry functions (several for <init>)
	decl  *decl           // for cobra roots
}

// analysis holds the immutable per-program state the traversal reads.
type analysis struct {
	cg      *callgraph.Graph
	declOf  map[*ssa.Function]*decl
	topDecl map[*ssa.Function]*ssa.Function // parents + generic origins, memoized
	succs   map[*ssa.Function][]*ssa.Function
}

func main() {
	rootDir := flag.String("root", ".", "module root")
	featuresPath := flag.String("features", "features.json", "feature mapping")
	outDir := flag.String("out", "out/reach", "output dir")
	algo := flag.String("algo", "vta", "callgraph algorithm: vta|cha")
	who := flag.String("who", "", "debug: print owners and callers of decls whose key contains this substring")
	maxFan := flag.Int("maxfanout", 60, "drop dynamic call sites resolving to more callees than this (VTA fallback noise)")
	trims := flag.String("trimprefix", "cmd/entire/cli.", "comma-separated module-relative prefixes trimmed from displayed symbol keys")
	flag.Parse()

	absRoot, err := filepath.Abs(*rootDir)
	cx.Check(err)
	cfg, err := cx.LoadConfig(*featuresPath)
	cx.Check(err)
	modPath, err := cx.ReadModulePath(absRoot)
	cx.Check(err)
	short := shortener(modPath, strings.Split(*trims, ","))

	t0 := time.Now()
	pkgs, err := packages.Load(&packages.Config{Mode: packages.LoadAllSyntax, Dir: absRoot}, "./...")
	cx.Check(err)
	if packages.PrintErrors(pkgs) > 0 {
		fmt.Fprintln(os.Stderr, "warning: some packages had errors; continuing")
	}
	fmt.Fprintf(os.Stderr, "loaded %d packages in %s\n", len(pkgs), time.Since(t0).Round(time.Millisecond))

	t0 = time.Now()
	prog, ssaPkgs := ssautil.AllPackages(pkgs, ssa.InstantiateGenerics)
	prog.Build()
	fmt.Fprintf(os.Stderr, "built SSA in %s\n", time.Since(t0).Round(time.Millisecond))

	allFuncs := ssautil.AllFunctions(prog)
	t0 = time.Now()
	var cg *callgraph.Graph
	if *algo == "cha" {
		cg = cha.CallGraph(prog)
	} else {
		cg = vta.CallGraph(allFuncs, nil)
	}
	fmt.Fprintf(os.Stderr, "callgraph (%s) with %d nodes in %s\n", *algo, len(cg.Nodes), time.Since(t0).Round(time.Millisecond))

	a := &analysis{cg: cg, declOf: map[*ssa.Function]*decl{}, topDecl: map[*ssa.Function]*ssa.Function{}, succs: map[*ssa.Function][]*ssa.Function{}}
	fset := prog.Fset
	isModule := func(fn *ssa.Function) bool {
		return fn.Pkg != nil && strings.HasPrefix(fn.Pkg.Pkg.Path(), modPath)
	}

	// Index top-level, non-test decls with metrics.
	for fn := range allFuncs {
		if !isModule(fn) || fn.Parent() != nil || fn.Synthetic != "" {
			continue
		}
		fd, ok := fn.Syntax().(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		pos := fset.Position(fd.Pos())
		rel, _ := filepath.Rel(absRoot, pos.Filename)
		rel = filepath.ToSlash(rel)
		if strings.HasSuffix(rel, "_test.go") {
			continue
		}
		end := fset.Position(fd.End()).Line
		feat := cfg.For(rel)
		a.declOf[fn] = &decl{
			Key: short(fn.String()), Name: fd.Name.Name, File: rel, Line: pos.Line,
			LOC: end - pos.Line + 1, Cognit: gocognit.Complexity(fd),
			Feat: feat.Name, Area: feat.Area, Ranked: feat.Ranked,
		}
	}

	// Roots.
	var roots []*root
	cobraRoot := map[*ssa.Function]bool{}
	for fn, d := range a.declOf {
		sig := fn.Signature
		if sig.Results().Len() == 1 && isCobraCmdPtr(sig.Results().At(0).Type()) {
			cobraRoot[fn] = true
			roots = append(roots, &root{label: d.Key, kind: "cobra", fns: []*ssa.Function{fn}, decl: d})
		}
	}
	initRoot := &root{label: "<init>", kind: "init"}
	for _, p := range ssaPkgs {
		if p == nil || !strings.HasPrefix(p.Pkg.Path(), modPath) {
			continue
		}
		if f := p.Func("init"); f != nil {
			initRoot.fns = append(initRoot.fns, f)
		}
		if p.Pkg.Name() == "main" {
			if f := p.Func("main"); f != nil {
				roots = append(roots, &root{label: "<main:" + strings.TrimPrefix(p.Pkg.Path(), modPath+"/") + ">", kind: "main", fns: []*ssa.Function{f}})
			}
		}
	}
	roots = append(roots, initRoot)
	fmt.Fprintf(os.Stderr, "%d module decls, %d roots (%d cobra)\n", len(a.declOf), len(roots), len(cobraRoot))

	a.buildSuccs(allFuncs, *maxFan)

	// BFS per root over the precomputed graph. Never enter another cobra root
	// (or its closures) — its cost is its own.
	reach := map[*root]map[*ssa.Function]bool{}
	for _, r := range roots {
		seen := map[*ssa.Function]bool{}
		queue := []*ssa.Function{}
		for _, f := range r.fns {
			seen[f] = true
			queue = append(queue, f)
		}
		decls := map[*ssa.Function]bool{}
		for len(queue) > 0 {
			f := queue[0]
			queue = queue[1:]
			if td := a.top(f); a.declOf[td] != nil {
				decls[td] = true
				seen[td] = true // lets closures of generic instances be admitted via their origin
			}
			for _, s := range a.succs[f] {
				if seen[s] {
					continue
				}
				td := a.top(s)
				if cobraRoot[td] && (r.kind != "cobra" || td != r.fns[0]) {
					continue
				}
				// A closure can only run if its creator ran.
				if s.Parent() != nil && !seen[td] {
					continue
				}
				seen[s] = true
				queue = append(queue, s)
			}
		}
		reach[r] = decls
	}

	owners := map[*ssa.Function][]*root{}
	for r, set := range reach {
		for d := range set {
			owners[d] = append(owners[d], r)
		}
	}

	if *who != "" {
		a.explainWho(*who, owners, fset, absRoot)
	}

	var results []*cmdResult
	for r, set := range reach {
		res := &cmdResult{Root: r.label, Kind: r.kind, ExclFeatures: map[string]int{}, ReachFeatures: map[string]int{}}
		if r.decl != nil {
			res.File = r.decl.File
			res.Feature = r.decl.Feat
		}
		for d := range set {
			m := a.declOf[d]
			res.ReachDecls++
			res.ReachLOC += m.LOC
			res.ReachCognit += m.Cognit
			res.ReachFeatures[m.Feat] += m.LOC
			if len(owners[d]) == 1 {
				res.ExclDecls++
				res.ExclLOC += m.LOC
				res.ExclCognit += m.Cognit
				res.ExclFeatures[m.Feat] += m.LOC
			}
		}
		results = append(results, res)
	}
	sort.Slice(results, func(i, j int) bool {
		if results[i].ExclLOC != results[j].ExclLOC {
			return results[i].ExclLOC > results[j].ExclLOC
		}
		return results[i].Root < results[j].Root
	})

	var unreached []*decl
	for fn, d := range a.declOf {
		if len(owners[fn]) == 0 && !cobraRoot[fn] {
			unreached = append(unreached, d)
		}
	}
	sort.Slice(unreached, func(i, j int) bool {
		if unreached[i].File != unreached[j].File {
			return unreached[i].File < unreached[j].File
		}
		return unreached[i].Line < unreached[j].Line
	})

	hist := map[int]int{}
	histLOC := map[int]int{}
	for fn, d := range a.declOf {
		if cobraRoot[fn] {
			continue
		}
		hist[len(owners[fn])]++
		histLOC[len(owners[fn])] += d.LOC
	}

	cx.Check(os.MkdirAll(*outDir, 0o755))
	rows := make([][]string, 0, len(results))
	for _, r := range results {
		rows = append(rows, []string{r.Root, r.Kind, r.File, r.Feature, itoa(r.ReachDecls), itoa(r.ReachLOC), itoa(r.ReachCognit), itoa(r.ExclDecls), itoa(r.ExclLOC), itoa(r.ExclCognit), topFeatures(r.ExclFeatures, 3)})
	}
	cx.Check(cx.WriteCSV(filepath.Join(*outDir, "commands.csv"),
		[]string{"root", "kind", "file", "feature", "reach_decls", "reach_loc", "reach_cognit", "excl_decls", "excl_loc", "excl_cognit", "top_excl_features"}, rows))

	out := map[string]any{
		"module": modPath, "algo": *algo,
		"meta":  map[string]any{"maxfanout": *maxFan, "trimprefix": *trims},
		"roots": len(roots), "cobra_roots": len(cobraRoot), "decls": len(a.declOf),
		"commands": results, "owner_hist": hist, "owner_histloc": histLOC, "unreached": unreached,
	}
	b, err := json.MarshalIndent(out, "", " ")
	cx.Check(err)
	cx.Check(os.WriteFile(filepath.Join(*outDir, "reach.json"), b, 0o644))

	writeMarkdown(filepath.Join(*outDir, "reach.md"), *algo, len(roots), len(cobraRoot), len(a.declOf), hist, histLOC, results, unreached)
	fmt.Fprintf(os.Stderr, "wrote %s/{reach.md,reach.json,commands.csv}\n", *outDir)
}

// top returns the top-level declaration a function belongs to: closures roll
// up through Parent, generic instantiations to their Origin. Memoized — it is
// consulted for every edge of every root's traversal.
func (a *analysis) top(fn *ssa.Function) *ssa.Function {
	if td, ok := a.topDecl[fn]; ok {
		return td
	}
	td := fn
	for td.Parent() != nil {
		td = td.Parent()
	}
	if o := td.Origin(); o != nil {
		td = o
	}
	a.topDecl[fn] = td
	return td
}

// buildSuccs precomputes each function's successors once: callgraph callees
// (with the fan-out cutoff applied to dynamic call sites), *ssa.Function
// operands (function values stored into fields, slices, maps), and nested
// closures. The traversal itself then only filters per root.
func (a *analysis) buildSuccs(allFuncs map[*ssa.Function]bool, maxFan int) {
	siteFan := map[ssa.CallInstruction]int{}
	for _, n := range a.cg.Nodes {
		for _, e := range n.Out {
			if e.Site != nil {
				siteFan[e.Site]++
			}
		}
	}
	var ops []*ssa.Value
	for fn := range allFuncs {
		var out []*ssa.Function
		if n := a.cg.Nodes[fn]; n != nil {
			for _, e := range n.Out {
				if e.Site != nil && siteFan[e.Site] > maxFan {
					if cc := e.Site.Common(); cc != nil && cc.StaticCallee() == nil {
						continue
					}
				}
				out = append(out, e.Callee.Func)
			}
		}
		for _, b := range fn.Blocks {
			for _, ins := range b.Instrs {
				ops = ins.Operands(ops[:0])
				for _, op := range ops {
					if op == nil {
						continue
					}
					if f, ok := (*op).(*ssa.Function); ok {
						out = append(out, f)
					}
				}
			}
		}
		out = append(out, fn.AnonFuncs...)
		if len(out) > 0 {
			a.succs[fn] = out
		}
	}
}

// explainWho prints, for every decl whose key contains substr, its owners and
// its incoming call edges (with each site's fan-out from the same map the
// cutoff uses, so the diagnostic can never describe a different filter).
func (a *analysis) explainWho(substr string, owners map[*ssa.Function][]*root, fset *token.FileSet, absRoot string) {
	siteFan := map[ssa.CallInstruction]int{}
	for _, n := range a.cg.Nodes {
		for _, e := range n.Out {
			if e.Site != nil {
				siteFan[e.Site]++
			}
		}
	}
	for fn, d := range a.declOf {
		if !strings.Contains(d.Key, substr) {
			continue
		}
		var labels []string
		for _, r := range owners[fn] {
			labels = append(labels, r.label)
		}
		sort.Strings(labels)
		fmt.Fprintf(os.Stderr, "WHO %s:%d %s -> %d owners: %s\n", d.File, d.Line, d.Key, len(labels), strings.Join(labels, ", "))
		n := a.cg.Nodes[fn]
		if n == nil {
			continue
		}
		for _, e := range n.In {
			site, kind := "?", "static"
			if e.Site != nil {
				site = strings.TrimPrefix(fset.Position(e.Site.Pos()).String(), absRoot+"/")
				if cc := e.Site.Common(); cc != nil {
					if cc.IsInvoke() {
						kind = "invoke"
					} else if cc.StaticCallee() == nil {
						kind = "dynamic"
					}
				}
			}
			fmt.Fprintf(os.Stderr, "    <- %s [%s, site fan-out %d] at %s\n", e.Caller.Func.String(), kind, siteFan[e.Site], site)
		}
	}
}

func writeMarkdown(path, algo string, nRoots, nCobra, nDecls int, hist, histLOC map[int]int, results []*cmdResult, unreached []*decl) {
	var sb strings.Builder
	fmt.Fprintf(&sb, "# Command reachability (%s)\n\n%d roots (%d cobra, plus <init> and one per main package), %d module decls.\n\n", algo, nRoots, nCobra, nDecls)
	fmt.Fprintf(&sb, "## How shared is the code? (decls by number of roots reaching them)\n\n| reached by N roots | decls | LOC |\n|---:|---:|---:|\n")
	var ks []int
	for k := range hist {
		ks = append(ks, k)
	}
	sort.Ints(ks)
	for _, k := range ks {
		fmt.Fprintf(&sb, "| %d | %d | %d |\n", k, hist[k], histLOC[k])
	}
	fmt.Fprintf(&sb, "\n## Per root (sorted by exclusive LOC)\n\n| root | kind | reach LOC | reach cognit | excl LOC | excl cognit | top exclusive features |\n|---|---|---:|---:|---:|---:|---|\n")
	for _, r := range results {
		fmt.Fprintf(&sb, "| `%s` | %s | %d | %d | %d | %d | %s |\n", r.Root, r.Kind, r.ReachLOC, r.ReachCognit, r.ExclLOC, r.ExclCognit, topFeatures(r.ExclFeatures, 3))
	}
	fmt.Fprintf(&sb, "\n## Decls reached by no root (%d)\n\nNothing in the shipped binaries references these (tests excluded; reflection not modelled).\n\n| feature | unreached LOC |\n|---|---:|\n", len(unreached))
	byFeat := map[string]int{}
	for _, d := range unreached {
		byFeat[d.Feat] += d.LOC
	}
	for _, kv := range sortedKV(byFeat) {
		fmt.Fprintf(&sb, "| %s | %d |\n", kv.k, kv.v)
	}
	fmt.Fprintf(&sb, "\n<details><summary>full list</summary>\n\n")
	for _, d := range unreached {
		fmt.Fprintf(&sb, "- `%s:%d` %s (%d loc, cog %d)\n", d.File, d.Line, d.Key, d.LOC, d.Cognit)
	}
	fmt.Fprintf(&sb, "\n</details>\n")
	cx.Check(os.WriteFile(path, []byte(sb.String()), 0o644))
}

func isCobraCmdPtr(t types.Type) bool {
	p, ok := t.(*types.Pointer)
	if !ok {
		return false
	}
	n, ok := p.Elem().(*types.Named)
	if !ok {
		return false
	}
	return n.Obj().Name() == "Command" && n.Obj().Pkg() != nil && strings.HasSuffix(n.Obj().Pkg().Path(), "spf13/cobra")
}

type kv struct {
	k string
	v int
}

func sortedKV(m map[string]int) []kv {
	var out []kv
	for k, v := range m {
		out = append(out, kv{k, v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].v != out[j].v {
			return out[i].v > out[j].v
		}
		return out[i].k < out[j].k
	})
	return out
}

func topFeatures(m map[string]int, n int) string {
	var parts []string
	for i, e := range sortedKV(m) {
		if i >= n {
			break
		}
		parts = append(parts, fmt.Sprintf("%s=%d", e.k, e.v))
	}
	return strings.Join(parts, " ")
}

// shortener trims the module path (and the given module-relative prefixes)
// from displayed symbol keys. Presentation-only; applied where keys are
// emitted, never to the analysis itself.
func shortener(mod string, trims []string) func(string) string {
	return func(s string) string {
		for _, tp := range trims {
			if tp = strings.TrimSpace(tp); tp != "" {
				s = strings.ReplaceAll(s, mod+"/"+tp, "")
			}
		}
		return strings.ReplaceAll(s, mod+"/", "")
	}
}

func itoa(i int) string { return strconv.Itoa(i) }

// dupl rolls a golangci-lint dupl JSON report up by feature, so the pipeline
// step the README describes actually exists in the tree.
//
//	golangci-lint run -c dupl-config.yaml --new=false --output.json.path=dupl.json ./...
//	dupl -in dupl.json -features features.json -root . -out dupl-by-feature.json
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"cxtool/internal/cx"
)

// golangciReport is the slice of golangci-lint's JSON output this tool reads.
type golangciReport struct {
	Issues []struct {
		Text string `json:"Text"`
		Pos  struct {
			Filename string `json:"Filename"`
			Line     int    `json:"Line"`
		} `json:"Pos"`
	} `json:"Issues"`
}

type pair struct {
	File      string `json:"file"`
	Line      int    `json:"line"`
	Other     string `json:"other"`
	OtherLine int    `json:"other_line"`
	Span      int    `json:"span"`
}

type crossPair struct {
	A string `json:"a"`
	B string `json:"b"`
	N int    `json:"n"`
}

var (
	otherRe = regexp.MustCompile("`([^`:]+):(\\d+)-(\\d+)`")
	spanRe  = regexp.MustCompile(`^(\d+)-(\d+) lines`)
)

func main() {
	in := flag.String("in", "dupl.json", "golangci-lint JSON report (dupl linter)")
	featuresPath := flag.String("features", "features.json", "feature mapping")
	rootDir := flag.String("root", ".", "repository root, for normalizing the report's relative paths")
	out := flag.String("out", "dupl-by-feature.json", "output file")
	flag.Parse()

	cfg, err := cx.LoadConfig(*featuresPath)
	cx.Check(err)
	absRoot, err := filepath.Abs(*rootDir)
	cx.Check(err)

	b, err := os.ReadFile(*in)
	cx.Check(err)
	var rep golangciReport
	cx.Check(json.Unmarshal(b, &rep))

	// golangci emits paths relative to its own working directory (often a
	// chain of ../..); resolve against the repo root.
	norm := func(fn string) string {
		if !filepath.IsAbs(fn) {
			fn = filepath.Join(absRoot, fn)
		}
		if rel, err := filepath.Rel(absRoot, fn); err == nil && !strings.HasPrefix(rel, "..") {
			return filepath.ToSlash(rel)
		}
		return filepath.ToSlash(fn)
	}

	prod := map[string]int{}
	lines := map[string]int{}
	test := map[string]int{}
	cross := map[[2]string]int{}
	var pairs []pair
	for _, it := range rep.Issues {
		fn := norm(it.Pos.Filename)
		feat := cfg.For(fn).Name
		span := 0
		if m := spanRe.FindStringSubmatch(it.Text); m != nil {
			a, _ := strconv.Atoi(m[1])
			b, _ := strconv.Atoi(m[2])
			span = b - a + 1
		}
		if strings.HasSuffix(fn, "_test.go") {
			test[feat]++
			continue
		}
		prod[feat]++
		lines[feat] += span
		if m := otherRe.FindStringSubmatch(it.Text); m != nil {
			other := norm(m[1])
			otherLine, _ := strconv.Atoi(m[2])
			pairs = append(pairs, pair{File: fn, Line: it.Pos.Line, Other: other, OtherLine: otherLine, Span: span})
			if of := cfg.For(other).Name; of != feat {
				k := [2]string{feat, of}
				if k[0] > k[1] {
					k[0], k[1] = k[1], k[0]
				}
				cross[k]++
			}
		}
	}

	sort.Slice(pairs, func(i, j int) bool { return pairs[i].Span > pairs[j].Span })
	if len(pairs) > 40 {
		pairs = pairs[:40]
	}
	var crossOut []crossPair
	for k, n := range cross {
		crossOut = append(crossOut, crossPair{A: k[0], B: k[1], N: n})
	}
	sort.Slice(crossOut, func(i, j int) bool {
		if crossOut[i].N != crossOut[j].N {
			return crossOut[i].N > crossOut[j].N
		}
		return crossOut[i].A < crossOut[j].A
	})

	res := map[string]any{
		"total":            len(rep.Issues),
		"prod_by_feature":  prod,
		"lines_by_feature": lines,
		"test_by_feature":  test,
		"cross":            crossOut,
		"largest":          pairs,
	}
	j, err := json.MarshalIndent(res, "", " ")
	cx.Check(err)
	cx.Check(os.WriteFile(*out, j, 0o644))
	fmt.Fprintf(os.Stderr, "%d issues (%d prod, %d test) -> %s\n", len(rep.Issues), sum(prod), sum(test), *out)
}

func sum(m map[string]int) int {
	t := 0
	for _, v := range m {
		t += v
	}
	return t
}

#!/usr/bin/env python3
"""Render the complexity baseline page from cxtool + reach + dupl outputs.

usage: render.py <out_dir_all> <reach_dir> <dupl_by_feature.json> <repo_root> <html_out>

Reads report.json / reach.json / dupl-by-feature.json only; the CSVs are for
humans and CI diffs. Rank policy (which features count in rankings) comes from
the data, which carries it from features.json — nothing here re-decides it.
The "Reading the numbers" section is interpretation written against one
snapshot; its inline figures are literals on purpose and go stale with the
tree, which the section says itself.
"""
import json, math, subprocess, sys, html, datetime, statistics, collections

OUT, REACH, DUPL, REPO, HTML_OUT = sys.argv[1:6]

def esc(s): return html.escape(str(s), quote=True)
def num(n): return f"{int(n):,}"

# ---------- load ----------
report = json.load(open(f"{OUT}/report.json"))
reach = json.load(open(f"{REACH}/reach.json"))
dupl = json.load(open(DUPL))
meta = report["meta"]
features, areas, files, funcs = report["features"], report["areas"], report["files"], report["funcs"]
COGNIT_WARN, COV_WARN = meta["cognit_warn"], meta["cov_warn"]
MAXFAN = reach["meta"]["maxfanout"]
commit = subprocess.run(["git", "-C", REPO, "rev-parse", "--short", "HEAD"], capture_output=True, text=True).stdout.strip()
today = datetime.date.today().isoformat()

def cov(row):  # -1 = no statements known
    return -1 if row["stmts"] == 0 else 100 * row["covered"] / row["stmts"]

def ratio(row):
    return 0 if row["prod_loc"] == 0 else row["test_loc"] / row["prod_loc"]

def density(row):
    return 0 if row["prod_loc"] == 0 else 100 * row["sum_cognit"] / row["prod_loc"]

for f in features:
    f["cov"], f["ratio"], f["density"] = cov(f), ratio(f), density(f)
    f["commits_90d"] = f["churn"].get("90d", {}).get("commits", 0)
    f["dupl"] = dupl["prod_by_feature"].get(f["name"], 0)

ranked_feature = {f["name"]: f["ranked"] for f in features}
core = [f for f in features if f["ranked"]]
tot_prod = sum(f["prod_loc"] for f in core); tot_test = sum(f["test_loc"] for f in core)
tot_stmts = sum(f["stmts"] for f in core); tot_cov = sum(f["covered"] for f in core)
tot_over = sum(f["funcs_over_cognit"] for f in core); tot_funcs = sum(f["funcs"] for f in core)
gen_loc = sum(a["gen_loc"] for a in areas)
median_cov = statistics.median(f["cov"] for f in core if f["cov"] >= 0)

hist = {int(k): v for k, v in reach["owner_histloc"].items()}
excl_loc = hist.get(1, 0)
CORE_ROOTS = 20  # "reached by ≥ this many roots" = the shared substrate
core_loc = sum(v for k, v in hist.items() if k >= CORE_ROOTS)
bucket_vals = [
    ("no root", hist.get(0, 0)),
    ("1 root", excl_loc),
    ("2–5", sum(v for k, v in hist.items() if 2 <= k <= 5)),
    ("6–19", sum(v for k, v in hist.items() if 6 <= k < CORE_ROOTS)),
    (f"{CORE_ROOTS}+", core_loc),
]

cobra = [c for c in reach["commands"] if c["kind"] == "cobra"]
pseudo = [c for c in reach["commands"] if c["kind"] != "cobra"]
top_cmds = sorted(cobra, key=lambda c: -c["excl_loc"])[:26]

def command(suffix):
    """The interpretation section quotes these; a rename must fail loudly,
    never render as zero."""
    for c in cobra:
        if c["root"].endswith(suffix):
            return c
    raise KeyError(f"no cobra root matching {suffix!r} in reach.json")

REV, INV, PREPUSH, EXPERTS = command("review.NewCommand"), command("investigate.NewCommand"), command("newHooksGitPrePushCmd"), command("newExpertsCmd")
EXP_TOTAL = REV["excl_loc"] + INV["excl_loc"] + EXPERTS["excl_loc"]

unreached = [u for u in reach["unreached"] if u["ranked"]]
un_by_file = collections.defaultdict(lambda: {"n": 0, "loc": 0, "cog": 0, "names": []})
for u in unreached:
    b = un_by_file[u["file"]]
    b["n"] += 1; b["loc"] += u["loc"]; b["cog"] += u["cognit"]; b["names"].append(u["name"])
un_files = sorted(un_by_file.items(), key=lambda kv: -kv[1]["loc"])[:22]
un_total = sum(u["loc"] for u in unreached)

prod_funcs = [fn for fn in funcs if ranked_feature[fn["feature"]]]
def covp(fn): return -1 if fn["stmts"] == 0 else 100 * fn["covered"] / fn["stmts"]
top_funcs = sorted(prod_funcs, key=lambda x: -x["cognit"])[:15]
undercov_all = [fn for fn in prod_funcs if fn["cognit"] >= COGNIT_WARN and fn["stmts"] > 0 and covp(fn) < COV_WARN]
undercov = sorted(undercov_all, key=lambda x: -x["cognit"])[:22]
hot_files = sorted(
    ((fl["churn"].get("90d", {}).get("commits", 0), fl) for fl in files
     if not fl["is_test"] and not fl["generated"] and fl["ranked"] and fl["sum_cognit"] > 0),
    key=lambda t: -(t[0] * t[1]["sum_cognit"]))
hot_files = [(c, fl) for c, fl in hot_files if c > 0][:15]

# ---------- svg: scatter ----------
def scatter():
    W, H = 920, 470; L, R_, T, B = 64, 24, 20, 56
    pts = [f for f in core if f["cov"] >= 0 and f["sum_cognit"] > 0]
    xmin, xmax = 50, 4000
    def X(v): return L + (math.log10(max(v, xmin)) - math.log10(xmin)) / (math.log10(xmax) - math.log10(xmin)) * (W - L - R_)
    def Y(v): return T + (100 - v) / 100 * (H - T - B)
    def Rr(loc): return max(5, min(22, 3 + math.sqrt(loc) / 7))
    grp = lambda a: "command" if a == "command" else ("capture" if a in ("capture", "agents") else "infra")
    parts = [f'<svg class="chart" viewBox="0 0 {W} {H}" role="img" aria-labelledby="sc-title" style="width:100%;height:auto"><title id="sc-title">Cognitive complexity vs statement coverage, per feature</title>']
    for yv in (0, 25, 50, 75, 100):
        parts.append(f'<line x1="{L}" x2="{W-R_}" y1="{Y(yv):.1f}" y2="{Y(yv):.1f}" class="grid"/><text x="{L-8}" y="{Y(yv)+4:.1f}" class="tick" text-anchor="end">{yv}%</text>')
    for xv in (100, 300, 1000, 3000):
        parts.append(f'<line y1="{T}" y2="{H-B}" x1="{X(xv):.1f}" x2="{X(xv):.1f}" class="grid"/><text y="{H-B+18}" x="{X(xv):.1f}" class="tick" text-anchor="middle">{xv}</text>')
    parts.append(f'<text x="{(L+W-R_)/2:.0f}" y="{H-8}" class="axis" text-anchor="middle">Σ cognitive complexity (log scale)</text>')
    parts.append(f'<text transform="translate(14,{(T+H-B)/2:.0f}) rotate(-90)" class="axis" text-anchor="middle">statement coverage</text>')
    # One stable labelling rule: the 12 features with the most under-covered complexity.
    label = set(f["name"] for f in sorted(pts, key=lambda f: -f["uncovered_cognit"])[:12])
    for f in sorted(pts, key=lambda f: -f["prod_loc"]):
        x, y, r = X(f["sum_cognit"]), Y(f["cov"]), Rr(f["prod_loc"])
        tip = f'{f["name"]} — Σcognit {num(f["sum_cognit"])}, coverage {f["cov"]:.0f}%, {num(f["prod_loc"])} prod LOC, uncovered cognit {f["uncovered_cognit"]}'
        parts.append(f'<circle class="dot g-{grp(f["area"])}" cx="{x:.1f}" cy="{y:.1f}" r="{r:.1f}" tabindex="0" data-tip="{esc(tip)}"><title>{esc(tip)}</title></circle>')
    used = []
    for f in sorted((f for f in pts if f["name"] in label), key=lambda f: Y(f["cov"])):
        right = X(f["sum_cognit"]) < L + 0.70 * (W - L - R_)
        x = X(f["sum_cognit"]) + (Rr(f["prod_loc"]) + 5 if right else -(Rr(f["prod_loc"]) + 5))
        y = Y(f["cov"]) + 4
        anchor = "start" if right else "end"
        w = 7 * len(f["name"])
        x0, x1 = (x, x + w) if right else (x - w, x)
        while any(abs(y - uy) < 13 and x0 < ux1 and x1 > ux0 for ux0, ux1, uy in used): y += 13
        used.append((x0, x1, y))
        parts.append(f'<text x="{x:.1f}" y="{y:.1f}" class="lbl" text-anchor="{anchor}">{esc(f["name"])}</text>')
    parts.append("</svg>")
    return "".join(parts)

def bar(v, vmax, cls="bar"):
    w = 0 if vmax == 0 else max(1.5, 100 * v / vmax)
    return f'<span class="{cls}"><i style="width:{w:.1f}%"></i></span>'

def cov_cell(c):
    if c < 0: return '<td class="n">n/a</td>'
    chip = ""
    if c < 50: chip = ' <span class="chip crit">▲ low</span>'
    elif c < 65: chip = ' <span class="chip ser">▲ low</span>'
    return f'<td class="n" data-v="{c:.1f}">{bar(c,100,"bar cov")}<span>{c:.0f}%</span>{chip}</td>'

# ---------- html ----------
def feature_rows():
    shown = [f for f in features if f["area"] != "generated"]
    mx_loc = max(f["prod_loc"] for f in shown); mx_cog = max(f["sum_cognit"] for f in shown)
    rows = []
    for f in sorted(shown, key=lambda f: -f["sum_cognit"]):
        rows.append(
            f'<tr data-area="{esc(f["area"])}">'
            f'<td class="name"><span class="fname">{esc(f["name"])}</span></td>'
            f'<td><span class="area">{esc(f["area"])}</span></td>'
            f'<td class="n" data-v="{f["prod_loc"]}">{bar(f["prod_loc"],mx_loc)}<span>{num(f["prod_loc"])}</span></td>'
            f'<td class="n" data-v="{f["ratio"]}">{f["ratio"]:.2f}</td>'
            f'<td class="n" data-v="{f["sum_cognit"]}">{bar(f["sum_cognit"],mx_cog)}<span>{num(f["sum_cognit"])}</span></td>'
            f'<td class="n" data-v="{f["density"]}">{f["density"]:.1f}</td>'
            f'<td class="n" data-v="{f["funcs_over_cognit"]}">{f["funcs_over_cognit"]}</td>'
            f'{cov_cell(f["cov"])}'
            f'<td class="n" data-v="{f["uncovered_cognit"]}">{f["uncovered_cognit"]}</td>'
            f'<td class="n" data-v="{f["commits_90d"]}">{f["commits_90d"]}</td>'
            f'<td class="n" data-v="{f["dupl"]}">{f["dupl"] or "·"}</td>'
            "</tr>")
    return "\n".join(rows)

def cmd_rows():
    mx = max(c["excl_loc"] for c in top_cmds)
    out = []
    for c in top_cmds:
        top = sorted(c["excl_features_loc"].items(), key=lambda kv: -kv[1])
        main = top[0][0] if top else "—"
        out.append(f'<tr><td class="mono">{esc(c["root"])}</td><td><span class="fname">{esc(main)}</span></td>'
                   f'<td class="n">{bar(c["excl_loc"],mx)}<span>{num(c["excl_loc"])}</span></td><td class="n">{num(c["excl_cognit"])}</td><td class="n muted">{num(c["reach_loc"])}</td></tr>')
    return "\n".join(out)

def func_row(fn):
    return (f'<tr><td class="n">{fn["cognit"]}</td><td class="n">{fn["cyclo"]}</td><td class="n">{fn["loc"]}</td>'
            f'{cov_cell(covp(fn))}<td><span class="fname">{esc(fn["feature"])}</span></td>'
            f'<td class="mono small">{esc(fn["file"])}:{fn["start"]} <b>{esc(fn["name"])}</b></td></tr>')

def hot_rows():
    return "\n".join(
        f'<tr><td class="n">{c}</td><td class="n">{fl["sum_cognit"]}</td><td class="n">{num(fl["loc"])}</td>{cov_cell(cov_file(fl))}'
        f'<td><span class="fname">{esc(fl["feature"])}</span></td><td class="mono small">{esc(fl["rel"])}</td></tr>'
        for c, fl in hot_files)

def cov_file(fl):
    return -1 if fl["stmts"] == 0 else 100 * fl["covered"] / fl["stmts"]

def unreached_rows():
    out = []
    for f, b in un_files:
        names = ", ".join(b["names"][:4]) + ("…" if len(b["names"]) > 4 else "")
        out.append(f'<tr><td class="n">{b["loc"]}</td><td class="n">{b["n"]}</td><td class="n">{b["cog"]}</td><td class="mono small">{esc(f)}<br><span class="muted">{esc(names)}</span></td></tr>')
    return "\n".join(out)

def dupl_rows():
    by = dupl["prod_by_feature"]; lines = dupl["lines_by_feature"]; prod = {f["name"]: f["prod_loc"] for f in features}
    return "\n".join(
        f'<tr><td><span class="fname">{esc(name)}</span></td><td class="n">{n}</td><td class="n">~{lines.get(name,0)}</td><td class="n">{1000*lines.get(name,0)/max(1,prod.get(name,1)):.0f}</td></tr>'
        for name, n in sorted(by.items(), key=lambda kv: -kv[1])[:12])

def largest_dupl():
    seen = set(); out = []
    for d in dupl["largest"]:
        key = tuple(sorted([(d["file"], d["line"]), (d["other"], d["other_line"])]))
        if key in seen: continue
        seen.add(key)
        out.append(f'<li><b>{d["span"]} lines</b> <span class="mono small">{esc(d["file"])}:{d["line"]}</span> ≡ <span class="mono small">{esc(d["other"])}:{d["other_line"]}</span></li>')
        if len(out) >= 7: break
    return "\n".join(out)

def bucket_bars():
    mx = max(v for _, v in bucket_vals)
    return "\n".join(f'<tr><td>{esc(l)}</td><td class="n">{bar(v,mx)}<span>{num(v)}</span></td></tr>' for l, v in bucket_vals)

area_tiles = "".join(
    f'<div class="tile"><div class="tlabel">{esc(a["name"])}</div><div class="tval">{num(a["prod_loc"])}</div><div class="tsub">prod LOC · {cov(a):.1f}% cov · ratio {ratio(a):.2f}</div></div>'
    for a in sorted(areas, key=lambda a: -a["prod_loc"]) if a["name"] != "generated")

